css:
.row {
  display: flex;
  gap: 12px;
  max-width: 360px;
  padding: 12px;
  border: 2px dashed #a1a1aa;
}

.label {
  flex-shrink: 0;
  font-weight: 600;
}

.code {
  flex: 1;
  min-width: 0; /* let the block shrink below its content */
  overflow-x: auto;
  padding: 8px 10px;
  background: #18181b;
  color: #fafafa;
  border-radius: 6px;
  font-family: monospace;
}
